mapper.select:
SELECT COUNT(*) AS totalRecords, SUM(CASE WHEN hr.score < h.pass_score THEN 1 ELSE 0 END) AS unqualifiedCount, SUM(CASE WHEN hr.score >= h.pass_score AND hr.score < GREATEST(h.pass_score, h.score * #{goodRatio}) THEN 1 ELSE 0 END) AS qualifiedCount, SUM(CASE WHEN hr.score >= GREATEST(h.pass_score, h.score * #{goodRatio}) AND hr.score < GREATEST(GREATEST(h.pass_score, h.score * #{goodRatio}), h.score * #{excellentRatio}) THEN 1 ELSE 0 END) AS goodCount, SUM(CASE WHEN hr.score >= GREATEST(GREATEST(h.pass_score, h.score * #{goodRatio}), h.score * #{excellentRatio}) THEN 1 ELSE 0 END) AS excellentCount FROM edu_homework_record hr JOIN edu_homework h ON hr.homework_id = h.id AND h.deleted = 0 AND h.status IN (1, 2) WHERE hr.deleted = 0 AND hr.status = 2 AND h.status IN (1, 2)
AND h.teacher_id = #{teacherId}
AND h.class_id IN #{cid}
AND h.course_id = #{courseId}
AND COALESCE(NULLIF(TRIM(h.semester_name), ''), (SELECT TRIM(binding.semester_name) FROM edu_class_course binding WHERE binding.class_id = h.class_id AND binding.course_id = h.course_id AND binding.deleted = 0 AND binding.status = 0 LIMIT 1)) LIKE CONCAT(#{academicYear}, '-', #{academicYear} + 1, '%')

SELECT h.id AS homeworkId, h.homework_name AS workName, ROUND(AVG(hr.score), 1) AS avgScore, MAX(hr.score) AS maxScore, MIN(hr.score) AS minScore FROM edu_homework h JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.deleted = 0 AND hr.status = 2 WHERE h.deleted = 0 AND h.status IN (1, 2) AND h.course_id = #{courseId}
AND h.class_id = #{classId}
GROUP BY h.id, h.homework_name, h.create_time ORDER BY h.create_time ASC

SELECT DISTINCT ec.id AS id, ec.class_name AS name FROM edu_class_course ecc JOIN edu_class ec ON ecc.class_id = ec.id AND ec.deleted = 0 AND ec.status = 0 JOIN capacity_course cc ON ecc.course_id = cc.id AND cc.deleted = 0 AND cc.status = 0 WHERE ecc.deleted = 0 AND ecc.status = 0 AND ecc.course_id = #{courseId}
AND cc.teacher_Id = #{teacherId}
ORDER BY ec.class_name

SELECT ec.id FROM edu_class ec JOIN system_dept d_major ON ec.dept_id = d_major.id AND d_major.deleted = 0 LEFT JOIN system_dept d_college ON d_major.parent_id = d_college.id AND d_college.deleted = 0 WHERE ec.deleted = 0 AND ec.status = 0
AND d_college.id = #{collegeId}
AND d_major.id = #{majorId}

SELECT h.id AS homeworkId, h.homework_name AS homeworkName, ROUND(AVG(hr.score), 1) AS avgScore FROM edu_homework h JOIN edu_homework_record hr ON h.id = hr.homework_id AND hr.deleted = 0 AND hr.status = 2 WHERE h.deleted = 0 AND h.status IN (1, 2) AND h.course_id = #{courseId}
AND h.class_id = #{classId}
GROUP BY h.id, h.homework_name, h.create_time ORDER BY h.create_time ASC
